package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public class RoadPerspectiveTest{
 public static void main(String[] args)throws Exception{ByteBuffer b=ByteBuffer.wrap(Files.readAllBytes(Paths.get(args[0]))).order(ByteOrder.LITTLE_ENDIAN);int[] reciprocal=new int[32768];for(int i=0;i<32768;i++)reciprocal[i]=b.getInt();int cases=b.getInt(),valid=0,invalid=0,words=0;for(int i=0;i<cases;i++){int[] p=new int[16];for(int j=0;j<16;j++)p[j]=b.getInt();int cap=b.getInt(),ok=b.getInt(),count=b.getInt();NativeRoadPerspective.Plan plan=null;try{plan=NativeRoadPerspective.plan(p,reciprocal,cap);}catch(IllegalArgumentException e){if(ok!=0)throw new AssertionError("Unexpected rejection "+i,e);}if(ok==0){if(plan!=null)throw new AssertionError("Accepted invalid "+i);invalid++;continue;}if(plan==null||plan.runs.length!=count)throw new AssertionError("Count "+i);for(int r=0;r<count;r++)for(int j=0;j<16;j++){if(plan.runs[r][j]!=b.getInt())throw new AssertionError("Run word "+i+":"+r+":"+j);words++;}for(int j=0;j<16;j++){if(plan.end[j]!=b.getInt())throw new AssertionError("Final word "+i+":"+j);words++;}valid++;}if(b.hasRemaining())throw new AssertionError("Trailing");System.out.println("PASS_ROAD_PERSPECTIVE cases="+cases+" valid="+valid+" rejected="+invalid+" words="+words);}
}
